python3 << 'PY'
import csv
from collections import Counter

with open('/app/dataset/hospital_compensation_registry.csv') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

by_pid = {r['patient_id']: r for r in rows}

ec_counts = Counter()
for r in rows:
    ec = r['emergency_contact_patient_id']
    if ec:
        ec_counts[ec] += 1

has_claim = set()
for r in rows:
    if r['record_date'] and r['record_date'].strip():
        has_claim.add(r['patient_id'])

no_claims = []
for pid, r in by_pid.items():
    if pid not in has_claim:
        no_claims.append((pid, ec_counts[pid]))

# Sort by how often they are listed as EC
no_claims.sort(key=lambda x: (-x[1], x[0]))
for pid, c in no_claims[:15]:
    print(pid, c, by_pid[pid]['compensation_reason'], by_pid[pid]['coverage_status'])
